from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_rows = {r for r in range(h) if len(set(grid[r])) == 1}
    sep_cols = {c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1}

    def segments(length, separators):
        out = []
        start = 0
        for i in range(length):
            if i in separators:
                if start < i:
                    out.append((start, i))
                start = i + 1
        if start < length:
            out.append((start, length))
        return out

    row_segments = segments(h, sep_rows)
    col_segments = segments(w, sep_cols)

    field = [
        grid[r][c]
        for r in range(h) if r not in sep_rows
        for c in range(w) if c not in sep_cols
    ]
    background = Counter(field).most_common(1)[0][0]

    result = []
    for r0, r1 in row_segments:
        row = []
        for c0, c1 in col_segments:
            count = sum(
                grid[r][c] != background
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            row.append(1 if count >= 2 else background)
        result.append(row)
    return result
